def _seed_templates() -> None:
    import uuid

    from app.services.catalog import TEMPLATES

    rows = [
        {
            'id': uuid.uuid4(),
            'code': t['code'],
            'category': t['category'],
            'title': t['title'],
            'description': t['description'],
            'icon': t['icon'],
            'prayer_name': t.get('prayer_name'),
            'default_time': t.get('default_time'),
            'default_duration_min': t.get('default_duration_min'),
            'default_target': t.get('default_target'),
            'unit': t.get('unit'),
            'min_version': t.get('min_version'),
            'suitable_for': t['suitable_for'],
            'is_active': True,
            'sort_order': t['sort_order'],
        }
        for t in TEMPLATES
    ]
    # Enum ustunlari matn sifatida yuboriladi — cast kerak
    bind = op.get_bind()
    for row in rows:
        bind.execute(
            sa.text(
                "INSERT INTO task_templates (id, code, category, title, description, icon, prayer_name,"
                " default_time, default_duration_min, default_target, unit, min_version, suitable_for,"
                " is_active, sort_order) VALUES (:id, :code, CAST(:category AS category), "
                "CAST(:title AS jsonb), CAST(:description AS jsonb), :icon, CAST(:prayer_name AS prayer_name),"
                " :default_time, :default_duration_min, :default_target, CAST(:unit AS jsonb),"
                " CAST(:min_version AS jsonb), :suitable_for, :is_active, :sort_order)"
            ),
            {
                **row,
                'title': _json(row['title']),
                'description': _json(row['description']),
                'unit': _json(row['unit']),
                'min_version': _json(row['min_version']),
            },
        )


